from itertools import combinations
# points = pairs among 0..5, indexed 0-14 lexicographic
pairs=list(combinations(range(6),2))
print(list(enumerate(pairs)))
# recursive perfect matchings
def matchings(lst):
    if not lst:
        yield []
    else:
        a=lst[0]
        for i in range(1,len(lst)):
            b=lst[i]
            rest=lst[1:i]+lst[i+1:]
            for m in matchings(rest):
                yield [(a,b)]+m
match=list(matchings(list(range(6))))
# normalize pairs sorted, matching sorted lexicographically
norm=[]
for m in match:
    mp=tuple(sorted(tuple(sorted(p)) for p in m))
    norm.append(mp)
norm=sorted(norm)
print(len(norm))
for i,m in enumerate(norm): print(i+15,m)
# edges: point idx to line idx if pair in matching
pidx={p:i for i,p in enumerate(pairs)}
edges=[]
for li,m in enumerate(norm, start=15):
    for p in m:
        edges.append((pidx[p],li))
edges=sorted(edges)
print(len(edges))
print(edges)
# Verify degrees, girth
n=30
adj=[set() for _ in range(n)]
for u,v in edges:
    adj[u].add(v); adj[v].add(u)
print([len(a) for a in adj], sum(len(a) for a in adj)//2)
from collections import deque
girth=10**9
for s in range(n):
    dist=[-1]*n; par=[-1]*n
    dist[s]=0; q=deque([s])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if dist[v]<0:
                dist[v]=dist[u]+1; par[v]=u; q.append(v)
            elif par[u]!=v and par[v]!=u:
                girth=min(girth, dist[u]+dist[v]+1)
print('girth',girth)
